function uniq(prefix,arr){let i=1,v;const set=new Set((arr||[]).map(x=>String(x.number||'')));do{v=prefix+'-'+String(i++).padStart(5,'0')}while(set.has(v));return v}
const prod=(c,id)=>c.db.products.find(x=>x.id===id);
const wh=(c,id)=>c.db.warehouses.find(x=>x.id===id);
function variants(c,pid){return c.db.productVariants.filter(x=>x.productId===pid&&x.active!==false)}
function uomFactor(c,pid,uom){const p=prod(c,pid);if(!p||!uom||uom===p.baseUom)return 1;return n(c.db.uomConversions.find(x=>x.productId===pid&&x.uom===uom)?.factor||1)}
function inTransit(c,pid,wid){return c.db.transferOrders.filter(t=>t.status==='in_transit'&&t.productId===pid&&(t.from===wid||t.to===wid)).reduce((s,t)=>s+(t.to===wid?n(t.qty):-n(t.qty)),0)}
function variantStock(c,id,wid){return c.db.stockMoves.filter(m=>m.variantId===id&&(!wid||m.warehouseId===wid)).reduce((s,m)=>s+(['delivery','out','return_supplier'].includes(m.type)?-n(m.qty):n(m.qty)),0)}

