 return base+`<div class="pr-grid2"><section class="card"><div class="card-head"><h3>Variants حقيقية</h3><button class="btn sm" id="newVariant">＋ Variant</button></div>${vs.slice(-15).reverse().map(v=>`<div class="stat-row"><div class="grow"><strong>${c.esc(prod(c,v.productId)?.nameAr||'')} • ${c.esc(v.name)}</strong><div class="sub">${c.esc(v.sku)} • مخزون ${variantStock(c,v.id,c.warehouse()?.id)}</div></div><strong>${c.fmt(v.price||prod(c,v.productId)?.price||0)}</strong></div>`).join('')||'<div class="empty">لا توجد متغيرات</div>'}</section><section class="card"><div class="card-head"><h3>وحدات القياس</h3><button class="btn sm" id="newUom">＋ تحويل</button></div>${us.slice(-15).reverse().map(x=>`<div class="stat-row"><div class="grow"><strong>${c.esc(prod(c,x.productId)?.nameAr||'')}</strong><div class="sub">1 ${c.esc(x.uom)} = ${x.factor} ${c.esc(prod(c,x.productId)?.baseUom||'قطعة')}</div></div></div>`).join('')||'<div class="empty">لا توجد تحويلات</div>'}</section></div><div class="card"><div class="card-head"><h3>Barcode Labels</h3><button class="btn outline" id="printLabels">طباعة ملصقات</button></div><div class="sub">اسم المنتج + السعر + SKU/Barcode بتنسيق ملصقات للمخزن.</div></div>`;
