 document.querySelector('#newVariant')?.addEventListener('click',()=>{c.openModal('Variant جديد',variantForm(c),false);setTimeout(()=>{const f=document.querySelector('#variantForm');if(f)f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),sku=String(fd.get('sku')||'').trim();if(c.db.productVariants.some(v=>v.sku===sku)||c.db.products.some(p=>p.sku===sku)){c.toast('SKU مستخدم مسبقاً');return}c.db.productVariants.push({id:c.uid('var'),companyId:c.db.session.companyId,productId:fd.get('productId'),name:fd.get('name'),sku,barcode:fd.get('barcode'),price:n(fd.get('price')),cost:n(fd.get('cost')),active:true,createdAt:c.now()});c.audit('إنشاء Variant','Product',sku);c.save('تم حفظ Variant');c.closeModal();c.render()}},0)});
