function idbOpen(){return new Promise((ok,no)=>{const r=indexedDB.open('NovaBluERP2',1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('state'))d.createObjectStore('state',{keyPath:'key'})};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
