function wizard(c,rows){if(rows.length<2)return c.toast('الملف فارغ');const h=rows[0],host=document.querySelector('#wizardPreview');host.innerHTML=`<div class="table-wrap"><table><tbody>${rows.slice(0,6).map(r=>`<tr>${r.map(v=>`<td>${c.esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="form-grid"><div class="field"><label>النوع</label><select id="wizType"><option value="products">منتجات</option><option value="customers">عملاء</option></select></div><div class="field"><label>عمود الاسم</label><select id="wizName">${h.map((x,i)=>`<option value="${i}">${c.esc(x)}</option>`).join('')}</select></div><div class="field"><label>عمود SKU/Phone</label><select id="wizKey">${h.map((x,i)=>`<option value="${i}">${c.esc(x)}</option>`).join('')}</select></div></div><button class="btn primary" id="wizRun">استيراد ${rows.length-1}</button>`;document.querySelector('#wizRun').onclick=()=>{const type=document.querySelector('#wizType').value,ni=n(document.querySelector('#wizName').value),ki=n(document.querySelector('#wizKey').value),ids=[];rows.slice(1).forEach(r=>{if(!r[ni])return;if(type==='products'){const key=String(r[ki]||'').trim();if(key&&c.db.products.some(p=>p.sku===key))return;const id=c.uid('p');c.db.products.push({id,companyId:c.db.session.companyId,nameAr:r[ni],nameEn:'',sku:key||'IMP-'+id.slice(-5),barcode:'',categoryId:'',unit:'قطعة',baseUom:'قطعة',uoms:['قطعة'],cost:0,price:0,tax:0,trackStock:true,reorder:0,active:true});ids.push(id)}else{const key=String(r[ki]||'').trim();if(key&&c.db.customers.some(x=>x.phone===key))return;const id=c.uid('c');c.db.customers.push({id,companyId:c.db.session.companyId,name:r[ni],phone:key,email:'',address:'',taxId:'',notes:'',creditLimit:0,createdAt:c.now()});ids.push(id)}});c.db.importJobs.unshift({id:c.uid('imp'),type,ids,at:c.now(),undone:false});c.save('تم استيراد '+ids.length);c.render()}}

